import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.BUOFcz_J.js";const u=JSON.parse('{"title":"Real-time task panel Agent episode","description":"","frontmatter":{},"headers":[],"relativePath":"records/plugin-agent-episode.md","filePath":"records/plugin-agent-episode.md"}'),r={name:"records/plugin-agent-episode.md"};function s(i,e,d,p,c,l){return a(),o("div",null,[...e[0]||(e[0]=[n('<div class="warning custom-block"><p class="custom-block-title">Historical record</p><p>This page records what happened on a date, with its observed failures and limits. It is not a requirement for the current implementation. Current behaviour is in <a href="/Rho/docs/reference/status">Status</a>.</p></div><h1 id="real-time-task-panel-agent-episode" tabindex="-1">Real-time task panel Agent episode <a class="header-anchor" href="#real-time-task-panel-agent-episode" aria-label="Permalink to &quot;Real-time task panel Agent episode&quot;">​</a></h1><p>Observed on 2026-11-13 in the Rho checkout on macOS with Node 22.22.3. The experiment used a temporary HOME, temporary project, temporary Rho service and Claude Code through the local Magpie gateway. It did not read or restart the user&#39;s Rho service.</p><h2 id="prompt" tabindex="-1">Prompt <a class="header-anchor" href="#prompt" aria-label="Permalink to &quot;Prompt&quot;">​</a></h2><p>The Agent was given exactly this sentence:</p><blockquote><p>请在当前 Rho 项目里创建一个实时任务面板插件，让我能随时打开它查看任务、Agent 工作状态和最近的进展，并把它接入工作区；请自行完成开发、验证和接入。</p></blockquote><h2 id="setup-and-attempts" tabindex="-1">Setup and attempts <a class="header-anchor" href="#setup-and-attempts" aria-label="Permalink to &quot;Setup and attempts&quot;">​</a></h2><p>The temporary Rho service started successfully on a loopback port and created a project with the generated <code>.rho/README.md</code>. The first driver attempt stopped before the model turn because it passed the removed <code>dontAsk</code> permission mode. The driver was corrected for Claude Code 2.1.323 and restricted to the temporary project, plugin commands and file tools.</p><p>The first Claude route returned:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-light vp-code" tabindex="0"><code><span class="line"><span>403 fusecode-lab: 组织余额不足，请联系管理员充值</span></span></code></pre></div><p>The local Magpie configuration then showed the actual model-picker route <code>auto/deepseek-v4.1-flash[1m]</code> and the local listeners <code>127.0.0.1:3425</code> and <code>127.0.0.1:3430</code>. The <code>magpie-server/deepseek-v4.1-flash</code> spelling was rejected as an unrecognized model. No provider or remote service configuration was changed.</p><p>With the exact local route, DeepSeek first interpreted “plugin” as a Claude Code plugin. It spent 40 turns reading Claude plugin types, created an incomplete <code>.claude-plugin</code> package and a marketplace file, and never produced a Rho package. This exposed two Rho gaps. The project note did not distinguish the two plugin systems, and the experiment driver had removed Bash entirely through restricted mode.</p><p>Rho&#39;s generated <code>.rho/README.md</code> now names <code>rho plugin create</code>, <code>rho plugin check</code> and <code>rho plugin dev</code>, and explicitly distinguishes <code>rho-plugin.json</code> from Claude Code&#39;s <code>.claude-plugin</code> format. The next run allowed only the exact Rho plugin commands. DeepSeek then created <code>task-panel</code>, edited its host, view and Skill, and ran the Rho checker.</p><h2 id="observed-successful-loop" tabindex="-1">Observed successful loop <a class="header-anchor" href="#observed-successful-loop" aria-label="Permalink to &quot;Observed successful loop&quot;">​</a></h2><p>The generated package contains a read-only <code>read-status</code> operation that delegates to <code>task.map.read</code>, <code>agent.sessions.list</code> and <code>agent.sessions.read</code>. Its view renders loading, empty, error and refreshed states. The generated package passed the Rho checker with <code>runtime.host: passed</code> and its operation state <code>passed</code>.</p><p>The disposable service installed the package at digest <code>7be90b0022ad04519011508a4e2571880808e95fb874c62148ef2af1629fad25</code>. Through the local browser principal, Plugins showed the package, its view, Skill and operation. Opening the view showed the empty-state task and Agent sections. Chrome checks at 1440 px and 390 px captured the page and found no horizontal overflow. A direct <code>extension.call</code> returned <code>completed</code> with task map, agents, counts, progress and errors fields.</p><p>The retained screenshots are <a href="https://github.com/YuLab-SMU/Rho/blob/main/docs/plugin-agent-acceptance/2026-11-13/plugins-1440.png" target="_blank" rel="noreferrer">Plugins at 1440 px</a>, <a href="https://github.com/YuLab-SMU/Rho/blob/main/docs/plugin-agent-acceptance/2026-11-13/plugins-390.png" target="_blank" rel="noreferrer">Plugins at 390 px</a>, <a href="https://github.com/YuLab-SMU/Rho/blob/main/docs/plugin-agent-acceptance/2026-11-13/task-panel-1440.png" target="_blank" rel="noreferrer">the panel at 1440 px</a> and <a href="https://github.com/YuLab-SMU/Rho/blob/main/docs/plugin-agent-acceptance/2026-11-13/task-panel-390.png" target="_blank" rel="noreferrer">the panel at 390 px</a>.</p><p>The dev watcher also passed its update episode. An invalid host edit retained the old digest. A valid edit selected digest <code>3142c474ee82ccb2938092fa6e4e4942a921f5385539fd16be22947e85d33ece</code>, and restoring the source returned the original digest.</p><p><code>rho plugin check</code> now imports the host in a child process and runs every declared operation with bounded sample input. The result reports the host and operation states as JSON. <code>rho plugin dev</code> performs the same check before installing a new snapshot and keeps the previous selection after a failed check. The Plugins page now has an explicit <strong>Refresh plugins</strong> action for loading a new package digest.</p><p>The runtime check proves host import and operation control flow. It does not prove the actual project data, authorization or browser layout; the Studio follow-up below supplies that separate browser evidence.</p><h2 id="studio-follow-up" tabindex="-1">Studio follow-up <a class="header-anchor" href="#studio-follow-up" aria-label="Permalink to &quot;Studio follow-up&quot;">​</a></h2><p>The runtime HTML plugin is now also a <code>rho.extension.html@1</code> Studio composition leaf. Its props keep the plugin id, view entry and selected package digest. A layout change therefore retains an exact package identity, while an update, disable or removal leaves the view readable and shows a recovery message instead of silently switching revisions. The follow-up Chrome episode records the real composition, responsive screenshots, stale-digest state and recovery.</p><p>The disposable follow-up passed these checks:</p><ul><li><code>rho plugin check</code> accepted the generated host and rejected a broken host without installing it.</li><li>The Plugins page&#39;s <strong>Open in Studio</strong> action inserted the view into the saved <code>workspace</code> composition. The 1440 px and 390 px screenshots are <a href="https://github.com/YuLab-SMU/Rho/blob/main/docs/plugin-agent-acceptance/2026-11-13/task-panel-studio-1440.png" target="_blank" rel="noreferrer">here</a> and <a href="https://github.com/YuLab-SMU/Rho/blob/main/docs/plugin-agent-acceptance/2026-11-13/task-panel-studio-390.png" target="_blank" rel="noreferrer">here</a>; both had no horizontal overflow.</li><li>Updating the package left the old digest in the layout until an explicit <strong>Reload plugin view</strong> showed the stale state. A conditional <code>props</code> operation reopened the same view id at the new digest.</li><li>Disable, enable and removal were observed in the view. Removal retained the composition leaf and its receipt. The stale, disabled and removed screenshots are <a href="https://github.com/YuLab-SMU/Rho/blob/main/docs/plugin-agent-acceptance/2026-11-13/task-panel-stale.png" target="_blank" rel="noreferrer">recorded</a>, <a href="https://github.com/YuLab-SMU/Rho/blob/main/docs/plugin-agent-acceptance/2026-11-13/task-panel-disabled.png" target="_blank" rel="noreferrer">here</a> and <a href="https://github.com/YuLab-SMU/Rho/blob/main/docs/plugin-agent-acceptance/2026-11-13/task-panel-removed.png" target="_blank" rel="noreferrer">here</a>.</li></ul><p>The machine-readable episode report is <a href="https://github.com/YuLab-SMU/Rho/blob/main/docs/plugin-agent-acceptance/2026-11-13/runtime-plugin-studio-report.json" target="_blank" rel="noreferrer"><code>runtime-plugin-studio-report.json</code></a>.</p>',25)])])}const g=t(r,[["render",s]]);export{u as __pageData,g as default};
